  const [head = [], ...rows] = values || [];
  const keys = head.map((h) => String(h).trim().toLowerCase());
  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));
}

const g = $input.first().json;
const alerts = {
  handoff: '🙋 Клиент просит человека',
  forward: '💬 Новое сообщение в диалоге, переданном вам',
};
const title = alerts[g.kind];
let alert_html = '';
if (title) {
  const c = g.customer || {};
  alert_html = [
    `<b>${title}</b>`,
    `Канал: ${g.channel === 'telegram' ? 'Telegram' : 'сайт'} · <code>${escapeHtml(g.session_id)}</code>`,
    c.name && `Имя: ${escapeHtml(c.name)}`,
    c.email && `Email: ${escapeHtml(c.email)}`,
    c.phone && `Телефон: ${escapeHtml(c.phone)}`,
    c.telegram && `Telegram: ${escapeHtml(c.telegram)}`,
    '',
    `<blockquote>${escapeHtml(g.text || '')}</blockquote>`,
    g.flags?.includes('daily_limit') ? '\n⚠️ Исчерпан дневной лимит ответов модели (daily_agent_runs).' : '',
  ].filter((x) => x !== false && x !== undefined && x !== null).join('\n').trim();
}
return [{ json: {
  kind: g.kind,
  channel: g.channel,
  session_id: g.session_id,
  customer: g.customer,
  text: g.text || '',
  reply: g.reply,
  reply_html: escapeHtml(g.reply),
  handoff: g.kind === 'handoff' || g.kind === 'forward',
  alert_html,
  tools: [],
  flags: g.flags || [],
  expose: {},
  debug: Boolean(g.debug),
} }];

// Log Row: строка для листа Log и ответ вебхуку.
const d = $('Guard Out').isExecuted ? $('Guard Out').first().json : $('Canned').first().json;
const row = [
  new Date().toISOString(),
  d.session_id,
  d.channel,
  d.text,
  d.reply,
  d.tools.map((t) => t.name).join(', '),
  d.handoff ? 'да' : '',
  d.flags.join(', '),
  Object.keys(d.expose || {}).length ? JSON.stringify(d.expose) : '',
];
const response = { reply: d.reply, handoff: d.handoff, session_id: d.session_id.replace(/^web:/, '') };
Object.assign(response, d.expose || {});
if (d.debug) {
  response.tools = d.tools;
  response.flags = d.flags;
}
return [{ json: { ...d, row, response } }];

// Plan: проверяет вызов инструмента и решает, что прочитать из календаря.
